/* "In software terms" analogies, shown in tooltips and on the glossary page */
(function () {
  const SWE = {
    'Model': 'a function whose internal constants are learned from examples instead of written by hand',
    'Parameter (weight)': 'learned constants / internal state of the function',
    'Hyperparameter': 'config flags and env vars you set before the run',
    'Feature': 'input arguments / request fields',
    'Label': 'the expected value in a unit-test assertion',
    'Dataset': 'test fixtures: rows of (input, expected output)',
    'Training': 'an automated "fix the code until tests pass" loop that edits the constants',
    'Inference': 'running the app in production; weights are frozen',
    'Loss function': 'a numeric "how many tests fail, and how badly" score',
    'Gradient': 'sensitivity analysis: which constant to change, in which direction, by how much',
    'Backpropagation': 'blame propagation back through the call stack (reverse traversal of the operation DAG)',
    'Computational graph': 'a recorded trace / DAG of every operation, like a build dependency graph',
    'Autograd': 'a compiler pass that derives the gradient code from your forward code automatically',
    'Epoch': 'one full run of the whole test suite',
    'Mini-batch / batch size': 'a bulk request: process N records together for throughput',
    'Train / validation / test sets': 'dev tests / staging / final release gate',
    'Overfitting': 'code that passes tests by special-casing each test input',
    'Data leakage': 'test answers or future data accidentally present in your fixtures',
    'Distribution shift': 'production traffic no longer looks like what you tested on',
    'Checkpoint': 'a snapshot / build artifact of the weights you can restore',
    'Tensor': 'an n-dimensional array; its shape is its type signature',
    'Embedding': 'a learned lookup table Map<id, float[]>, i.e. serialising meaning into a vector',
    'Token': 'a lexeme produced by the lexer',
    'Tokenizer / tokenization': 'the lexer: text → stream of integer token IDs',
    'Vocabulary': 'the symbol table / enum of all tokens',
    'Attention': 'a soft hash-map lookup: compare a query with every key and return a weighted mix of values',
    'Query, Key, Value (Q, K, V)': 'lookup key you search with · keys stored in the map · values stored in the map',
    'Causal mask': 'access control: position t may not read anything after t',
    'Sliding-window attention': 'a ring buffer: only the last N entries are visible',
    'Bidirectional attention': 'read access to the whole document, past and future',
    'Sparse attention': 'local lookups plus a small global index everyone can read',
    'Online softmax': 'a streaming aggregate: keep a running max and running sum instead of loading every value first',
    'Ring attention': 'sharding a huge join across nodes that pass blocks around a ring',
    'KV cache': 'memoization of past computation during generation',
    'Prompt': 'the request payload',
    'Context window': 'maximum request size (buffer length) in tokens',
    'Temperature': 'a randomness / jitter knob',
    'Logits': 'raw ranking scores before normalisation',
    'Softmax': 'normalise scores into percentages that sum to 100%',
    'Fine-tuning': 'forking a mature library and continuing development on your own data',
    'LoRA': 'a small patch file applied over frozen base weights',
    'Quantization': 'using smaller numeric types (double → byte): lossy compression for weights',
    'RAG': 'search + template injection: fetch relevant docs and paste them into the prompt',
    'Hallucination': 'a confident wrong answer (undefined behaviour that looks valid)',
    'Guardrails': 'input validation / WAF / output filtering around the model',
    'Red-teaming': 'penetration testing for model behaviour',
    'Benchmark': 'a standard test suite / performance benchmark',
    'Pretraining': 'the expensive one-time "compile" of general knowledge into a base library',
    'Base model': 'a powerful library with no product interface yet',
    'SFT (supervised fine-tuning)': 'teaching the library a product API using example conversations',
    'RLHF': 'optimising against human A/B preference feedback',
    'Mixture of Experts (MoE)': 'an API gateway routing each request to a few specialist microservices',
    'Data / tensor / pipeline parallelism': 'replicas / sharding one table / assembly-line stages',
    'Continuous batching': 'dynamic request batching that admits new requests every tick',
    'PagedAttention / vLLM': 'virtual-memory paging for the KV cache',
    'Latency / throughput': 'exactly what it means for any backend: p99 per request vs requests per second',
    'Regularization': 'complexity constraints / lint rules against over-clever special cases',
    'Dropout': 'chaos engineering: randomly disable units during training',
    'Optimizer': 'the update / retry strategy for the weights',
    'Learning rate (LR)': 'step size of each automatic fix (like autoscaler aggressiveness)',
    'Neural network': 'a pipeline of matrix-multiply + non-linear transform stages',
    'Layer': 'one stage in a middleware pipeline',
    'Activation function': 'the non-linear step between stages; without it the pipeline collapses into one linear function',
    'Residual connection': 'each stage submits a patch (diff) to shared state instead of overwriting it',
    'Transformer block': 'join (attention: tokens share info) followed by map (FFN: per-token transform)',
    'Precision': 'of the alerts that fired, how many were real',
    'Recall': 'of the real incidents, how many triggered an alert',
    'Threshold': 'your alerting threshold',
    'Decoding / sampling': 'the client loop that picks the next token and calls the model again',
    'Perplexity': 'a quality metric: the effective number of choices the model hesitates between',
    'Flashattention': '',
    'FlashAttention': 'a cache-aware tiled algorithm, like a blocked join that never spills the full table',
    'GPU': 'a massively parallel worker pool for arithmetic',
    'Compute-bound vs memory-bound': 'CPU-bound vs I/O-bound',
  };
  TL.GLOSSARY.forEach((g) => { if (SWE[g.term]) g.swe = SWE[g.term]; });
})();
